// KeybUSB.cpp : Defines the entry point for the application.//#include "stdafx.h"#define __MAIN_FILE__#include "KeybCOM.h"#include "Resource.h"#include <ShellApi.h>#include <stdio.h>//#include "YokoUSB.h"#include "LogFile.h"CYokoUSB usb;#define MAX_LOADSTRING 100// Global Variables:TCHAR szTitle[MAX_LOADSTRING];// The title bar text// Forward declarations of functions included in this code module:ATOM MyRegisterClass(HINSTANCE hInstance, LPCTSTR pszClass);LRESULT CALLBACK	WndProc(HWND, UINT, WPARAM, LPARAM);LRESULT CALLBACK	About(HWND, UINT, WPARAM, LPARAM);NOTIFYICONDATA NI;//char szServer[256] = "";void StartService(void);void StopService(void);CLogFile gblLogFile;//UINT nIconMessage = ::RegisterWindowMessageA("¨лочка гори!!");//int APIENTRY _tWinMain(HINSTANCE hInstance, HINSTANCE , LPTSTR pszCmdLine, int nCmdShow)  {	  CLogFile::Initialize ("KeybUSB");	  //::DebugBreak();  if ( pszCmdLine[0] == '/' || pszCmdLine[0] == '-' )  if ( pszCmdLine[1] == 's' || pszCmdLine[1] == 'S' )    {    lstrcpy( szServer, pszCmdLine+2 );    }	MSG msg;	memset( &msg, 0, sizeof(msg) );	char szBuffer[_MAX_PATH + 1] = { 0 };    HWND hWnd;  if ( ::IsKeyUSB( hWnd ) )    {    return 0; //Запрет на несколько экземпляров    }  //  if ( !usb.OpenUSB() )    {    usb.CloseUSB();    return 0;    }  // Initialize global strings	LoadString(hInstance, IDS_APP_TITLE, szTitle, MAX_LOADSTRING);  //	MyRegisterClass(hInstance, szClassNameUSB);  //	// Perform application initialization:	if (!usb.Create(hInstance)) 	{    return FALSE;	}	//HACCEL hAccelTable = LoadAccelerators(hInstance, (LPCTSTR)IDC_KEYBCOM);	HACCEL hAccelTable = LoadAccelerators(hInstance, MAKEINTRESOURCE(IDC_KEYBUSB));	int nResult = 0;	// Main message loop:  //StartService();	while ( (nResult = GetMessage(&msg, NULL, 0, 0)) != 0 ) 	  {		  if ( nResult == -1 )		  {		  }		  else		  {			if ( !TranslateAccelerator(msg.hwnd, hAccelTable, &msg) )			{				TranslateMessage(&msg);				DispatchMessage(&msg);			}		  }	  }  //StopService();  usb.CloseUSB();  return (int) msg.wParam;  }//ATOM MyRegisterClass(HINSTANCE hInstance, LPCTSTR pszClass)  {  WNDCLASSEX wcex;  wcex.cbSize = sizeof(WNDCLASSEX);   wcex.style			= CS_HREDRAW | CS_VREDRAW;  wcex.lpfnWndProc	= (WNDPROC)WndProc;  wcex.cbClsExtra		= 0;  wcex.cbWndExtra		= 0;  wcex.hInstance		= hInstance;  wcex.hIcon			= LoadIcon(hInstance, (LPCTSTR)IDI_SMALL);  wcex.hCursor		= LoadCursor(NULL, IDC_ARROW);  wcex.hbrBackground	= (HBRUSH)::GetStockObject(BLACK_BRUSH);  wcex.lpszMenuName	= NULL;  wcex.lpszClassName	= pszClass;  wcex.hIconSm		= LoadIcon(wcex.hInstance, (LPCTSTR)IDI_SMALL);  NI.hIcon = wcex.hIconSm;  return RegisterClassEx(&wcex);  }//HWND  hViewWnd;//LRESULT CALLBACK WndProc(HWND hWnd, UINT uMsg, WPARAM wParam, LPARAM lParam)  {  //  if ( uMsg == nMessageKeyboard )    return usb.Write( wParam, lParam );  //  if ( uMsg == nIconMessage && lParam == WM_RBUTTONUP )    {    HMENU hMenu = ::CreatePopupMenu();    if ( hMenu )      {      UINT u = MF_BYCOMMAND | MF_ENABLED;      if ( ::IsWindowVisible(hWnd) )        ::AppendMenu(hMenu,u,101,"Спрятать окно");      else        ::AppendMenu(hMenu,u,100,"Показать окно");      ::AppendMenu(hMenu,MF_SEPARATOR,0,0);      ::AppendMenu(hMenu,u,102,"Завершить работу...");      ::AppendMenu(hMenu,u,103,"Выход из меню");      //      POINT point;      ::GetCursorPos( &point );	    ::SetForegroundWindow(hWnd); //?      ::TrackPopupMenu(hMenu,TPM_LEFTALIGN|TPM_LEFTBUTTON|TPM_RIGHTBUTTON,                   point.x,point.y,0,hWnd,NULL);      ::DestroyMenu(hMenu);      }    }  if ( uMsg == nIconMessage && lParam == WM_LBUTTONDBLCLK )    {    hViewWnd = hWnd;    ::ShowWindow( hWnd, SW_SHOWNORMAL );    ::SetForegroundWindow( hWnd );    }  //	switch (uMsg) 	  {    case WM_CREATE:      {      NI.cbSize = sizeof ( NI );       NI.hWnd = hWnd;       NI.uID = 1001;       NI.uFlags = NIF_ICON|NIF_MESSAGE|NIF_TIP;       NI.uCallbackMessage = nIconMessage;       lstrcpy ( NI.szTip,szTitle); 	    Shell_NotifyIcon( NIM_ADD, &NI );       }    break;    case WM_DESTROY:      {      static char szMessage[] =        "Завершение работы программы приведет\n"        "к отключению АРМ Оператора от клавиатуры.\n\n"        "Продолжить закрытие программы?";      int nReturn = ::MessageBox( hWnd, szMessage, szTitle,                        MB_YESNO | MB_ICONQUESTION | MB_DEFBUTTON2 );      if ( nReturn != IDYES )        return 0;  	  Shell_NotifyIcon( NIM_DELETE, &NI );       ::PostQuitMessage( 0 );      }    break;    case WM_SIZE:      {      if ( wParam == SIZE_MINIMIZED )        {        hViewWnd = NULL;        ::ShowWindow( hWnd, SW_HIDE );        }      }    break;  //    case WM_COMMAND:      switch ( LOWORD( wParam ) )        {        case 100:// Показать окно          hViewWnd = hWnd;          ::ShowWindow( hWnd, SW_SHOWNORMAL );          ::SetForegroundWindow( hWnd );          break;        case 101:// Спрятать окно          ::ShowWindow( hWnd, SW_HIDE );          break;        case 102:// Завершить работу          ::PostMessage( hWnd, WM_DESTROY, 0, 0 );          break;        case 103:// Выход          break;        case IDM_ABOUT:          DialogBox( ::GetModuleHandle(NULL), (LPCTSTR)IDD_ABOUTBOX, hWnd, (DLGPROC)About);        break;        case IDM_EXIT:          DestroyWindow(hWnd);        break;        default:          return DefWindowProc(hWnd, uMsg, wParam, lParam);        }		break;    case WM_ERASEBKGND:      {      if ( !usb.Paint( (HDC)wParam ) )        ::DefWindowProc( hWnd, uMsg, wParam, lParam );      return 0;      }    break;    default:      return DefWindowProc(hWnd, uMsg, wParam, lParam);    };  return 0;  }